@app.get("/students")
@app.get("/api/students")
def get_students(class_: Optional[List[str]] = QParam(None, alias="class")):
    if not class_:
        return {"students": STUDENTS}
    wanted = set(class_)
    return {"students": [s for s in STUDENTS if s["class"] in wanted]}


# ---------------- Q11: batch sentiment (POST /sentiment) ----------------
from vaderSentiment.vaderSentiment import SentimentIntensityAnalyzer

_analyzer = SentimentIntensityAnalyzer()
_analyzer.lexicon.update({
    "sad": -2.5, "unhappy": -2.5, "depressed": -2.8, "miserable": -2.8,
    "lonely": -2.0, "heartbroken": -3.0, "disappointed": -2.2, "upset": -2.0,
    "cry": -2.0, "crying": -2.0, "cried": -2.0, "tears": -1.5, "lost": -1.0,
    "broke": -1.0, "broken": -1.8, "failed": -2.0, "fail": -2.0, "sick": -1.8,
    "excited": 2.5, "thrilled": 3.0, "delighted": 3.0, "grateful": 2.5,
    "glad": 2.0, "joy": 2.8, "wonderful": 3.0, "awesome": 3.0, "amazing": 3.0,
})


class SentimentRequest(BaseModel):
    sentences: List[str]


def _classify(sentence: str) -> str:
    score = _analyzer.polarity_scores(sentence)["compound"]
    if score >= 0.05:
        return "happy"
    if score <= -0.05:
        return "sad"
    return "neutral"


@app.post("/sentiment")
@app.post("/api/sentiment")
def sentiment(req: SentimentRequest):
    return {"results": [{"sentence": s, "sentiment": _classify(s)} for s in req.sentences]}
